const blueprint = $('Get story blueprint').item.json;
const storyBible = $input.item.json;
const storyItem = $('Loop Over Items').item.json;

const storyId = storyItem.story_id || storyItem.id;

const staticData = $getWorkflowStaticData('global');
if (!staticData.counts) staticData.counts = {};
staticData.counts[storyId] = { success: 0, failed: 0 };

const TARGET_CULTURES = [
  "Tunisian"
];

return TARGET_CULTURES.map(culture => ({
  json: {
    story_id: storyId,
    target_culture: culture,
    blueprint,
    story_bible: storyBible
  }
}));

const item = $input.item.json;

const bp = item.blueprint?.blueprint || {};
const bible = item.story_bible?.bible || {};
const targetCulture = item.target_culture;
const storyId = item.story_id || bp.story_id || bible.story_id;

// --- PROTECTED ---
const protectedCharacters = (bible.characters || []).map(c => ({
  name: c.name,
  role: c.role,
  protected_attributes: c.protected_attributes || []
}));
const allCharacterNames = (bible.characters || []).map(c => c.name);

const protectedRelationships = (bible.relationships || [])
  .filter(r => r.is_protected)
  .map(r => ({
    source: r.source_character_id,
    target: r.target_character_id,
    type: r.relationship_type,
    description: r.description
  }));

const protectedWorldRules = (bible.world_rules || [])
  .filter(r => r.is_protected)
  .map(r => r.rule);

const protectedKeyEvents = (bp.key_events || [])
  .filter(e => e.is_protected)
  .map(e => ({
    description: e.description,
    narrative_function: e.narrative_function,
    importance: e.importance
  }));

const protectedElements = {
  characters: protectedCharacters,
  relationships: protectedRelationships,
  world_rules: protectedWorldRules,
  moral: bp.core_moral || [],
  key_events: protectedKeyEvents,
  continuity_constraints: bible.continuity_constraints || [],
  required_elements: bp.required_elements || []
};

// --- ADAPTABLE ---
const adaptableLocations = (bp.location_functions || [])
  .filter(l => l.adaptability === "flexible")
  .map(l => ({
    original: l.original_location,
    narrative_function: l.narrative_function
  }));

const adaptableSecondaryEvents = (bp.key_events || [])
  .filter(e => !e.is_protected)
  .map(e => e.description);

const adaptableEntities = (bible.important_entities || []).map(e => ({
  name: e.name,
  type: e.type,
  narrative_role: e.narrative_role
}));

const adaptableElements = {
  locations: adaptableLocations,
  adaptable_elements: bp.adaptable_elements || [],
  optional_elements: bp.optional_elements || [],
  secondary_events: adaptableSecondaryEvents,
  entities: adaptableEntities,
  daily_life: [],
  food: [],
  clothing: [],
  social_context: []
};

return {
  story_id: storyId,
  target_culture: targetCulture,
  source_title: bp.source_title || bible.source_title || "",
  story_type: bp.story_type || "",
  target_audience: bp.target_audience || "",
  protected_story_elements: protectedElements,
  adaptable_story_elements: adaptableElements,
protected_character_names: allCharacterNames,
  retry_count: 0 
};

const context = $('Cultural Adaptation Context').item.json;
const currentItem = $input.item.json;
const data = { ...context, retry_count: $input.item.json.retry_count || 0,
             last_failure_reason: currentItem.last_failure_reason || null};

const clean = (str) => (str || '')
  .toString()
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .trim();

const cleanArray = (arr) => (arr || []).map(x => clean(typeof x === 'string' ? x : JSON.stringify(x)));

const protectedEl = data.protected_story_elements || {};
const adaptableEl = data.adaptable_story_elements || {};

const protectedCharactersStr = (protectedEl.characters || [])
  .map(c => c.name + " (" + c.role + ", protected: " + (c.protected_attributes || []).join(", ") + ")")
  .join("; ");

const protectedRelationshipsStr = (protectedEl.relationships || [])
  .map(r => r.source + " -> " + r.target + " (" + r.type + "): " + clean(r.description))
  .join("; ");

const protectedRulesStr = cleanArray(protectedEl.world_rules).join("; ");
const protectedMoralStr = cleanArray(protectedEl.moral).join("; ");
const protectedEventsStr = (protectedEl.key_events || [])
  .map(e => clean(e.description) + " (" + e.narrative_function + ")")
  .join("; ");
const continuityStr = cleanArray(protectedEl.continuity_constraints).join("; ");

const characterNamesStr = (data.protected_character_names || []).join(", ");

const adaptableLocationsStr = (adaptableEl.locations || [])
  .map(l => clean(l.original) + " (" + l.narrative_function + ")")
  .join("; ");
const adaptableElementsStr = cleanArray(adaptableEl.adaptable_elements).join(", ");
const optionalElementsStr = cleanArray(adaptableEl.optional_elements).join(", ");
const secondaryEventsStr = cleanArray(adaptableEl.secondary_events).join("; ");
const entitiesStr = (adaptableEl.entities || [])
  .map(e => clean(e.name) + " (" + e.type + ", " + e.narrative_role + ")")
  .join("; ");

const outputSchema = "{" +
  "\"story_id\": \"\", " +
  "\"target_culture\": {\"country\": \"\", \"region\": \"\", \"language\": \"\"}, " +
  "\"adaptation_principles\": [\"\"], " +
  "\"setting\": {\"environment\": [], \"architecture\": [], \"geography\": [], \"climate\": [], \"public_spaces\": [], \"domestic_spaces\": []}, " +
  "\"social_context\": {\"family_dynamics\": [], \"social_interactions\": [], \"community_life\": [], \"forms_of_address\": []}, " +
  "\"cultural_elements\": {\"food\": [], \"clothing\": [], \"traditions\": [], \"music\": [], \"objects\": [], \"daily_life\": []}, " +
  "\"language_style\": {\"language\": \"\", \"register\": \"\", \"local_expressions\": [], \"restrictions\": []}, " +
  "\"cultural_mappings\": [{\"story_element\": \"\", \"element_type\": \"\", \"narrative_function\": \"\", \"target_representation\": \"\", \"adaptation_reason\": \"\"}], " +
  "\"preservation_rules\": [\"\"], " +
  "\"forbidden_adaptations\": [\"\"]" +
  "}";
function buildRetryFeedback(failure, retryCount) {
  if (!failure || retryCount === 0) return "";

  const parts = [];

  const schemaErr = failure.schema_errors || {};
  if ((schemaErr.missing_fields || []).length > 0) {
    parts.push("You omitted these required fields: " + schemaErr.missing_fields.join(", ") + ". Include all of them.");
  }
  if ((schemaErr.wrong_type_fields || []).length > 0) {
    parts.push("These fields must be JSON arrays, not another type: " + schemaErr.wrong_type_fields.join(", ") + ".");
  }
  if (schemaErr.mappings_malformed) {
    parts.push("Every object in cultural_mappings must include story_element, element_type, narrative_function, target_representation, AND adaptation_reason — one of these was missing or the array itself was malformed.");
  }

  const semViolations = failure.semantic_violations || [];
  semViolations.forEach(v => {
    if (v.includes("does not appear")) {
      parts.push(v + " Make sure this exact name is written verbatim somewhere in your output (e.g. in a cultural_mappings entry, preservation_rules, or forbidden_adaptations).");
    } else if (v.includes("No preservation_rules")) {
      parts.push("You must provide at least one entry in preservation_rules — list explicit rules protecting the story's protected elements.");
    } else if (v.includes("forbidden_adaptations is empty")) {
      parts.push("You must provide at least one entry in forbidden_adaptations, describing an adaptation that would break a protected character or element.");
    } else {
      parts.push(v);
    }
  });

  if (parts.length === 0) return "";

  return "\n\nRETRY FEEDBACK — YOUR PREVIOUS ATTEMPT (#" + retryCount + ") FAILED FOR THESE REASONS, FIX THEM THIS TIME:\n" +
    parts.map((p, i) => (i + 1) + ". " + p).join("\n") +
    "\nDo not repeat the same mistake. Everything else about the task is unchanged.";
}

const retryFeedback = buildRetryFeedback(data.last_failure_reason, data.retry_count);

const prompt =
  "You are a cultural narrative adaptation engine. Be direct and concise in your reasoning — do not over-explain, go straight to the structured output. Your task is NOT to rewrite the story. " +
  "Using the protected and adaptable elements below, generate a structured Locale Profile that defines " +
  "how culturally adaptable story elements should be represented in the target culture: " + clean(data.target_culture) + ". " +

  "Story: " + clean(data.source_title) + " (" + data.story_type + ", target audience " + data.target_audience + "). " +

  "CHARACTER NAME RULE: The following character names are part of the story's identity and must NEVER be renamed, translated, or replaced, regardless of whether their role, species, or setting is adapted: " + characterNamesStr + ". You may adapt a character's habitat, species-appropriate details, or cultural context, but the name itself must remain exactly as given, unchanged, in every part of your output. " +

  "PROTECTED ELEMENTS - DO NOT CHANGE: " +
  "Characters: " + protectedCharactersStr + ". " +
  "Relationships: " + protectedRelationshipsStr + ". " +
  "World rules: " + protectedRulesStr + ". " +
  "Core moral: " + protectedMoralStr + ". " +
  "Key protected events: " + protectedEventsStr + ". " +
  "Continuity constraints: " + continuityStr + ". " +

  "ADAPTABLE ELEMENTS - CAN BE REPRESENTED DIFFERENTLY IN TARGET CULTURE: " +
  "Flexible locations: " + adaptableLocationsStr + ". " +
  "Adaptable elements: " + adaptableElementsStr + ". " +
  "Optional elements: " + optionalElementsStr + ". " +
  "Secondary events: " + secondaryEventsStr + ". " +
  "Other entities: " + entitiesStr + ". " +

  "RULES: Preserve all protected elements exactly as narrative functions, even if surface representation changes. " +
  "Adapt only contextual and culturally dependent elements (habitat, species framing, objects, food, clothing, setting). " +
  "Never put a character name inside target_representation as if it were being replaced — keep the original name and only describe how their surroundings or context are localized. " +
  "Avoid stereotypes and unsupported cultural generalizations. " +
  "For each adaptable element you choose to map, explain the narrative function it serves and why your target representation preserves that function. " +
"SIZE LIMITS (to avoid truncation): each array in setting, social_context, cultural_elements and language_style has AT MOST 3 items; AT MOST 8 cultural_mappings; AT MOST 5 adaptation_principles, 5 preservation_rules, 5 forbidden_adaptations. Each string is ONE short sentence. " +
  "Respond ONLY with valid JSON matching exactly this schema, no extra text, no markdown fences, no reasoning shown in the output: " + outputSchema;

const finalPrompt = prompt + retryFeedback;

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/glm-5p3-flash",
  max_tokens: 12000,
  temperature: 0.2,
  reasoning_effort: "low",
  messages: [{ role: "user", content: finalPrompt }]
});

return {
  story_id: data.story_id,
  target_culture: data.target_culture,
  retry_count: data.retry_count,
  locale_prompt: finalPrompt,
  fireworks_body
};

const response = $input.item.json;
const promptData = $('Build Locale Profile Prompt').item.json;

let rawText = "";
try {
  rawText = response.choices[0].message.content;
} catch (e) {
  return {
    parse_error: true,
    error_message: "No content in LLM response (exception): " + e.message,
    raw_response: JSON.stringify(response),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

if (typeof rawText !== 'string' || rawText.trim() === '') {
  return {
    parse_error: true,
    error_message: "LLM response content is empty or not a string",
    raw_response: JSON.stringify(response),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Tentatives de réparation des erreurs JSON communes générées par le LLM
function tryFixCommonJsonErrors(text) {
  let fixed = text;
  // "]]" accidentel -> "]" (le schéma ne contient jamais de tableau de tableaux)
  fixed = fixed.replace(/\]\]/g, ']');
  // "}}" accidentel entre deux propriétés -> "}"
  fixed = fixed.replace(/\}\}(\s*,\s*")/g, '}$1');
  // guillemet fermant mal placé juste avant un crochet : \"] -> "]
  fixed = fixed.replace(/\\"\]/g, '"]');
  // virgule traînante avant } ou ]
  fixed = fixed.replace(/,(\s*[\}\]])/g, '$1');
  return fixed;
}

let localeProfile;
let usedFix = false;

try {
  localeProfile = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    const fixedText = tryFixCommonJsonErrors(cleanedText);
    localeProfile = JSON.parse(fixedText);
    usedFix = true;
  } catch (secondError) {
    return {
      parse_error: true,
      error_message: "JSON parse failed even after auto-fix: " + secondError.message + " (original error: " + firstError.message + ")",
      raw_response: cleanedText,
      story_id: promptData.story_id,
      target_culture: promptData.target_culture
    };
  }
}

return {
  parse_error: false,
  auto_fixed: usedFix,
  story_id: promptData.story_id,
  target_culture: promptData.target_culture,
  locale_profile: localeProfile,
  retry_count: promptData.retry_count || 0 
};

const item = $input.item.json;
if (item.parse_error) {
  return {
    ...item,
    schema_valid: false,
    schema_errors: { parse_failure: true, missing_fields: [], wrong_type_fields: [], mappings_malformed: false }
  };
}
const profile = item.locale_profile || {};

const requiredFields = [
  "target_culture",
  "adaptation_principles",
  "setting",
  "social_context",
  "cultural_elements",
  "language_style",
  "cultural_mappings",
  "preservation_rules",
  "forbidden_adaptations"
];

const missingFields = requiredFields.filter(f => profile[f] === undefined || profile[f] === null);

const arrayFields = ["adaptation_principles", "cultural_mappings", "preservation_rules", "forbidden_adaptations"];
const wrongTypeFields = arrayFields.filter(f => profile[f] !== undefined && !Array.isArray(profile[f]));

const mappingsValid = Array.isArray(profile.cultural_mappings)
  ? profile.cultural_mappings.every(m =>
      m && typeof m === "object" &&
      "story_element" in m && "target_representation" in m && "adaptation_reason" in m
    )
  : false;

const schemaValid = missingFields.length === 0 && wrongTypeFields.length === 0 && mappingsValid;

return {
  ...item,
  schema_valid: schemaValid,
  schema_errors: {
    missing_fields: missingFields,
    wrong_type_fields: wrongTypeFields,
    mappings_malformed: !mappingsValid
  }
};

const item = $input.item.json;
const profile = item.locale_profile || {};

const contextData = $('Cultural Adaptation Context').item.json;
const protectedEl = contextData.protected_story_elements || {};
const allNames = contextData.protected_character_names || [];

const violations = [];

const profileText = JSON.stringify(profile).toLowerCase();

// 1. Chaque nom de personnage principal doit apparaître tel quel dans le profil
allNames.forEach(name => {
  const nameLower = (name || "").toLowerCase();
  if (nameLower && !profileText.includes(nameLower)) {
    violations.push("Character name '" + name + "' does not appear anywhere in the locale profile — possible renaming.");
  }
});

// 2. preservation_rules ne doit pas être vide
const preservationRules = Array.isArray(profile.preservation_rules) ? profile.preservation_rules : [];
if (preservationRules.length === 0) {
  violations.push("No preservation_rules provided — protected elements are not explicitly guarded.");
}

// 3. forbidden_adaptations ne doit pas être vide s'il y a des personnages protégés
const forbidden = Array.isArray(profile.forbidden_adaptations) ? profile.forbidden_adaptations : [];
if (forbidden.length === 0 && allNames.length > 0) {
  violations.push("forbidden_adaptations is empty despite protected characters existing.");
}

const semanticValid = violations.length === 0;

return {
  ...item,
  semantic_valid: semanticValid,
  semantic_violations: violations,
  final_valid: item.schema_valid && semanticValid
};

const item = $input.item.json;
const retryCount = (item.retry_count || 0) + 1;

return {
  ...item,
  retry_count: retryCount,
  last_failure_reason: {
    schema_errors: item.schema_errors,
    semantic_violations: item.semantic_violations
  }
};

const item = $input.item.json;

return {
  json: {
    log_id: Date.now().toString(),
    workflow: 'locale_profile_generation',
    story_id: item.story_id,
    target_culture: item.target_culture,
    step: 'locale_profile_validation',
    status: 'failed_max_retries',
    retry_count: item.retry_count,
    message: 'Locale profile discarded after ' + item.retry_count + ' failed attempts.',
    last_failure_reason: JSON.stringify(item.last_failure_reason || {}),
    created_at: new Date().toISOString()
  }
};

function sanitizeEmptyArrays(value) {
  if (Array.isArray(value)) {
    if (value.length === 0) return null;
    return value.map(sanitizeEmptyArrays);
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = sanitizeEmptyArrays(value[key]);
    }
    return out;
  }
  return value;
}

const item = $json;

return [{
  json: {
    story_id: item.story_id,
    document_id: item.story_id + '_' + item.target_culture, 
    target_culture: item.target_culture,
    locale_profile: sanitizeEmptyArrays(item.locale_profile),
    schema_valid: item.schema_valid,
    semantic_valid: item.semantic_valid,
    status: 'validated',
    created_at: new Date().toISOString()
  }
}];

const staticData = $getWorkflowStaticData('global');
const storyId = $('Loop Over Items').item.json.story_id || $('Loop Over Items').item.json.id;
const counts = staticData.counts?.[storyId] || { success: 0, failed: 0 };

return [{
  json: {
    story_id: storyId,
    status: 'locale_profiles_generated',
    locale_profiles_success: counts.success,
    locale_profiles_failed: counts.failed,
    updated_at: new Date().toISOString()
  }
}];

const staticData = $getWorkflowStaticData('global');
const storyId = $('Loop Over Items').item.json.story_id || $('Loop Over Items').item.json.id;

if (!staticData.counts) staticData.counts = {};
if (!staticData.counts[storyId]) staticData.counts[storyId] = { success: 0, failed: 0 };

staticData.counts[storyId].success += 1;

return [$json];

const staticData = $getWorkflowStaticData('global');
const storyId = $('Loop Over Items').item.json.story_id || $('Loop Over Items').item.json.id;

if (!staticData.counts) staticData.counts = {};
if (!staticData.counts[storyId]) staticData.counts[storyId] = { success: 0, failed: 0 };

staticData.counts[storyId].failed += 1;

return [$json];
